list_products.code:
import (
	"fmt"
)

resp, err := client.Products().ListProducts(ctx, map[string]any{"limit": 20}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["products"].([]any) {
	product := row.(map[string]any)
	fmt.Println(product["id"], product["name"], product["sku"], product["base_price"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])

